import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowRight, FiCheckCircle, FiClock, FiGrid, FiLogOut, FiUser } from 'react-icons/fi';
import BrandMark from '../components/common/BrandMark';
import ErrorMessage from '../components/common/ErrorMessage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import { useAuth } from '../hooks/useAuth';
import { getClientProfile } from '../services/siteService';

const ClientProfile = () => {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const load = async () => {
    setLoading(true);
    try {
      const data = await getClientProfile();
      setProfile(data.client);
      setError('');
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load your client workspace.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) return (
    <div className="portal-page grid place-items-center">
      <LoadingSpinner message="Preparing your workspace…" />
    </div>
  );

  if (error) return (
    <div className="portal-page grid place-items-center">
      <ErrorMessage message={error} onRetry={load} />
    </div>
  );

  const stats = [
    { label: 'Active sites', value: profile?.stats?.active_sites || 0, icon: FiGrid },
    { label: 'Completed sites', value: profile?.stats?.completed_sites || 0, icon: FiCheckCircle },
    { label: 'Latest update', value: profile?.stats?.latest_update || 'N/A', icon: FiClock }
  ];

  return (
    <div className="portal-page">
      <div className="portal-shell profile-shell">

        {/* ========== SIDEBAR ========== */}
        <aside className="portal-sidebar">
          <div className="flex items-center gap-2 px-4 py-3">
            <BrandMark />
            <div className="text-xs">
              <div className="font-bold text-textPrimary">Aeroview 360</div>
              <div className="text-[10px] text-textMuted">Client Portal</div>
            </div>
          </div>

          <div className="portal-rule" />

          {/* ✅ Client Logo + Name in Sidebar */}
          <div className="flex items-center gap-3 px-4 py-3">
            {profile?.company_logo ? (
              <img
                src={profile.company_logo}
                alt={profile.client_name}
                className="w-10 h-10 rounded-lg object-cover border border-gray-200"
              />
            ) : (
              <div className="w-10 h-10 rounded-lg bg-primaryDark text-white flex items-center justify-center font-bold text-sm">
                {profile?.client_name?.slice(0, 2).toUpperCase()}
              </div>
            )}
            <div className="min-w-0">
              <div className="font-semibold text-sm text-textPrimary truncate">
                {profile?.client_name}
              </div>
              <div className="text-[10px] text-textMuted uppercase tracking-wider">Client Workspace</div>
            </div>
          </div>

          <div className="portal-rule" />

          <div className="portal-client px-4 py-3">
            <span className="text-xs text-textMuted">Signed in as</span>
            <strong className="text-sm block">{user?.name}</strong>
            <button
              onClick={() => { logout(); navigate('/login'); }}
              className="mt-2 text-sm text-red-500 hover:text-red-700"
            >
              <FiLogOut className="inline mr-1" /> Sign out
            </button>
          </div>
        </aside>

        {/* ========== MAIN CONTENT ========== */}
        <main className="portal-main">
          {/* ✅ Header with Client Logo instead of generic icon */}
          <header className="portal-header">
            <div className="portal-heading flex items-center gap-4">
              <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-gray-200 flex-shrink-0">
                {profile?.company_logo ? (
                  <img
                    src={profile.company_logo}
                    alt={profile.client_name}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full bg-gray-200 flex items-center justify-center text-gray-500 font-bold text-xl">
                    {profile?.client_name?.slice(0, 2).toUpperCase()}
                  </div>
                )}
              </div>
              <div>
                <h1 className="text-xl font-bold text-textPrimary">
                  Welcome Back, {user?.name?.split(' ')[0]}!
                </h1>
                <p className="text-sm text-textSecondary">
                  {profile?.client_name} • Client Dashboard
                </p>
              </div>
            </div>
          </header>

          <div className="portal-content">
            <section className="profile-hero">
              <div>
                <span className="text-xs font-semibold text-primaryDark uppercase tracking-wider">Client Dashboard</span>
                <h2 className="text-xl font-bold text-textPrimary mt-1">Everything about your project, in one clear view.</h2>
                <p className="text-textSecondary mt-1 text-sm">Select a site to access progress tours, videos, image folders, and final deliverables.</p>
                <button
                  onClick={() => navigate('/sites')}
                  className="mt-3 btn-primary inline-flex items-center gap-2 text-sm"
                >
                  View Project Sites <FiArrowRight />
                </button>
              </div>
            </section>

            <div className="portal-grid portal-grid--three">
              {stats.map(({ label, value, icon: Icon }) => (
                <div className="data-card stat-card" key={label}>
                  <span><Icon /></span>
                  <strong>{value}</strong>
                  <small>{label}</small>
                </div>
              ))}
            </div>

            <div className="info-bar">
              <FiCheckCircle /> Your account only displays sites and project content assigned to {profile?.client_name}.
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default ClientProfile;
